function [r] = omod(x, y)
%OMOD  Octave's mod(x, y) for doubles: 0 when y is not whole and x/y is within one relative eps of a whole number, else
%   x - y floor(x/y); the result takes the sign of y.
%   x: real[1] (passed a plain number)
%   y: real[1] (passed a plain number)
%   returns r: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    r = 0;
    if (y == 0)
        r = x;
    else
        q = (x / y);
        nint_y = floor((y + 0.5));
        nint_q = q;
        if isfinite(q)
            nint_q = floor((q + 0.5));
        end
        if ((nint_y ~= y) && (asils.pc.fabs(((q - nint_q) / nint_q)) < 2.220446049250313e-16))
            r = 0;
        else
            r = (x - (y * floor(q)));
        end
    end
    if ((x ~= y) && (y ~= 0))
        if (y < 0)
            r = (-(asils.pc.fabs(r)));
        else
            r = asils.pc.fabs(r);
        end
    end
end
